    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    prime_factors = 0
    for i in range(2, a + 1):
        if a % i == 0 and is_prime(i):
            prime_factors += 1
            while a % i == 0:
                a //= i
    return prime_factors == 3
